//! 🧪️ Four authored root-link leaves run their actual generated diagnostics, sparse decision, full inverse and physical close.
use crate::snapshot::original::EnergyModelSnapshot;
use crate::diff::original::EnergyModelDiff;
use protocol::{RetainedMutationLeaf,RetainedMutationLeafPreparation,RetainedMutationAdvance,RetainedMutationDecision,RetainedMutationCloseContext};
use semio_framework_value::{DslValue,retirement::RetireOwned};
#[path="../../../../📸️snapshot/🧳️state/🧪️tests/🧰️helpers/🦀️.rs"]mod helpers;
use helpers::{receive,source,grant,observe,drain,denied_axes};
use semio_framework_value_native_owned::native_decoding::NativeReceive;
#[derive(Debug,semio_framework_value::ToValue,semio_framework_value::FromValue,semio_framework_value::RetireOwned)]
#[value(tag="mutation",rename_all="camelCase")]
pub(super) enum Operation{BindWeatherFile(crate::BindWeatherFile),UnbindWeatherFile(crate::UnbindWeatherFile),ConnectReferencedModel(crate::ConnectReferencedModel),DisconnectReferencedModel(crate::DisconnectReferencedModel)}
macro_rules! from{($($name:ident),*)=>{$(impl From<crate::$name> for Operation{fn from(v:crate::$name)->Self{Self::$name(v)}})*}}
from!(BindWeatherFile,UnbindWeatherFile,ConnectReferencedModel,DisconnectReferencedModel);
impl protocol::Mutation<EnergyModelSnapshot> for Operation{type Diff=EnergyModelDiff;const DESCRIPTORS:&'static[protocol::MutationLeafDescriptor]=&[];fn descriptor(&self)->&'static protocol::MutationLeafDescriptor{panic!("actual authored link fixture directly calls its installed native leaf")}}
impl Operation{fn link(&self)->Option<&protocol::ArtifactLink>{match self{Self::BindWeatherFile(p)=>Some(&p.link),Self::ConnectReferencedModel(p)=>Some(&p.link),Self::UnbindWeatherFile(_)|Self::DisconnectReferencedModel(_)=>None}}}
pub(super) fn run<L>(slot:&str,attach:bool)where L:RetainedMutationLeaf<EnergyModelSnapshot,Operation>+NativeReceive<DslValue>+RetireOwned+Sync{
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../🧳️native/🔗️root/🧪️tests/🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap().iter().filter(|c|c["slot"]==slot&&attach!=c["value"].is_null()){
 let mut document:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut document=document["document"].take();document["model"]=helpers::corpus()["model"].clone();document[if slot=="weather_link"{"weatherLink"}else{"referencedModel"}]=case["before"].clone();let original=source(receive::<EnergyModelSnapshot>(&document));let input=source(receive::<L>(&if attach{serde_json::json!({"link":case["value"]})}else{serde_json::json!({})}));let mut owner=L::Preparation::new();
 for index in 0..100000{let d=owner.decision_demand(input.borrow(),original.borrow(),4096).unwrap();assert!(d.copy_bytes<=4096);let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.decide(input.borrow(),original.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.decision_demand(input.borrow(),original.borrow(),4096).unwrap(),d);}let(s,h)=observe(||owner.decide(input.borrow(),original.borrow(),4096,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){break}assert!(index<99999,"{} authored leaf decision did not finish",case["id"]);}
 let mut diff=None;let mut inverse=None;match owner.take_decision(){RetainedMutationDecision::Refused(messages)=>{assert!(matches!(case["outcome"].as_str(),Some("invalid"|"missing")));assert!(!messages.is_empty());drain(messages)},RetainedMutationDecision::Admitted(value,messages)=>{assert!(!matches!(case["outcome"].as_str(),Some("invalid"|"missing")));drain(messages);let value=source(value);for index in 0..100000{let d=owner.inverse_demand(input.borrow(),original.borrow(),value.borrow(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.inverse(input.borrow(),original.borrow(),value.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));}let(s,h)=observe(||owner.inverse(input.borrow(),original.borrow(),value.borrow(),4096,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){break}assert!(index<99999,"authored link inverse did not finish");}let rows=owner.take_inverse();if case["outcome"]=="changed"{assert_eq!(rows.len(),1);let expected=if case["before"].is_null(){None}else{Some(receive::<protocol::ArtifactLink>(&case["before"]))};assert_eq!(rows[0].link(),expected.as_ref());drain(expected);}else{assert!(rows.is_empty());}inverse=Some(rows);diff=Some(value);}}
 let factory=semio_framework_value::factory::OwnedValueRetirementFactory::<Operation>::default();let context=RetainedMutationCloseContext{mutations:&factory};owner.begin_close();for index in 0..100000{if owner.terminal_is_empty(){break}let d=owner.close_demand(context,4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.close_step(context,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));}let(s,h)=observe(||owner.close_step(context,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));assert!(index<99999,"authored link owner did not close");}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));if let Some(rows)=inverse{drain(rows)}if let Some(value)=diff{drain(value)}drain(input);drain(original);
 }
}
